// Audio helper. Every line Bobo says is looked up in the voice manifest
// (generated by `npm run voice`) and played as a recorded clip. Lines without
// a recording fall back to the browser's speech synthesis, so nothing is ever
// silent.
import manifest from '../data/voice-manifest.json'
import { voiceKey } from '../data/script.js'

const PREFERRED_VOICES = [
  'Google US English',
  'Microsoft Aria Online (Natural) - English (United States)',
  'Microsoft Jenny Online (Natural) - English (United States)',
  'Samantha',
  'Microsoft Zira - English (United States)',
]

let cachedVoice = null
let currentAudio = null
let muted = false
let defaultRate = 0.8
const NORMAL_RATE = 0.8

// Reuse audio elements so a clip only downloads once.
const clipCache = new Map()

function clipFor(text) {
  const file = manifest.lines?.[voiceKey(text)]
  if (file) return import.meta.env.BASE_URL + file
  if (import.meta.env.DEV) console.warn(`[voice] No recording for "${text}" — run npm run voice`)
  return null
}

function pickVoice() {
  if (cachedVoice) return cachedVoice
  if (typeof window === 'undefined' || !window.speechSynthesis) return null
  const voices = window.speechSynthesis.getVoices()
  if (!voices.length) return null
  cachedVoice =
    PREFERRED_VOICES.map((name) => voices.find((v) => v.name === name)).find(Boolean) ||
    voices.find((v) => v.lang === 'en-US') ||
    voices.find((v) => v.lang?.startsWith('en')) ||
    null
  return cachedVoice
}

if (typeof window !== 'undefined' && window.speechSynthesis) {
  // Voices load asynchronously in most browsers.
  window.speechSynthesis.onvoiceschanged = () => {
    cachedVoice = null
    pickVoice()
  }
}

export function setMuted(value) {
  muted = value
  if (muted) stop()
}

/** Speaking speed: 0.8 is normal. Applies to recordings and the browser voice. */
export function setRate(value) {
  defaultRate = value
}

export function isMuted() {
  return muted
}

// Each new request bumps this id, so a longer sequence stops as soon as the
// child taps something else.
let requestId = 0

// Bumped whenever playback is halted, so a delayed or interrupted line knows
// it has been superseded.
let haltCount = 0
let resolvePending = null

// Silence whatever is playing right now (used before every new line).
function halt() {
  haltCount += 1
  if (currentAudio) {
    currentAudio.pause()
    currentAudio = null
  }
  if (resolvePending) {
    resolvePending('stopped')
    resolvePending = null
  }
  if (typeof window !== 'undefined' && window.speechSynthesis) {
    window.speechSynthesis.cancel()
  }
}

/** Stop speaking and cancel any sequence that is still running. */
export function stop() {
  requestId += 1
  halt()
}

function speakWithSynthesis(text, { rate = defaultRate, pitch = 1.1 } = {}) {
  return new Promise((resolve) => {
    if (typeof window === 'undefined' || !window.speechSynthesis) {
      resolve()
      return
    }
    const utterance = new SpeechSynthesisUtterance(text)
    const voice = pickVoice()
    if (voice) utterance.voice = voice
    utterance.lang = voice?.lang || 'en-US'
    utterance.rate = rate
    utterance.pitch = pitch
    // Some browsers occasionally never fire onend; don't let a sequence hang.
    const fallback = setTimeout(resolve, 2500 + text.length * 120)
    const done = () => {
      clearTimeout(fallback)
      resolve()
    }
    utterance.onend = done
    utterance.onerror = done
    // Chrome can drop an utterance queued in the same tick as cancel(), so
    // wait a moment — but don't speak if something else started meanwhile.
    const token = haltCount
    setTimeout(() => {
      if (token === haltCount) window.speechSynthesis.speak(utterance)
      else done()
    }, 40)
  })
}

/**
 * Play a recorded clip. Resolves 'ended' or 'stopped' (interrupted by a new
 * line). Rejects only if the recording can't be loaded at all.
 */
function playClip(src) {
  return new Promise((resolve, reject) => {
    let audio = clipCache.get(src)
    if (!audio) {
      audio = new Audio(src)
      clipCache.set(src, audio)
    }
    audio.currentTime = 0
    // "Slow" voice speed also slows recordings (pitch is preserved).
    audio.playbackRate = defaultRate / NORMAL_RATE
    currentAudio = audio
    resolvePending = resolve
    const finish = (result) => {
      if (resolvePending === resolve) resolvePending = null
      resolve(result)
    }
    audio.onended = () => finish('ended')
    audio.onerror = () => {
      clipCache.delete(src)
      if (resolvePending === resolve) resolvePending = null
      reject(new Error(`Could not load ${src}`))
    }
    audio.play().catch((err) => {
      // AbortError = interrupted by the next line; NotAllowedError = the
      // browser blocked sound. Neither should switch to the robot voice.
      if (err.name === 'NotSupportedError') {
        if (resolvePending === resolve) resolvePending = null
        reject(err)
      } else finish('stopped')
    })
  })
}

async function speakOne(text, options = {}) {
  halt()
  const src = options.src || clipFor(text)
  if (src) {
    try {
      await playClip(src)
      return
    } catch {
      // The recording is missing or broken — use the browser voice instead.
    }
  }
  await speakWithSynthesis(text, options)
}

/**
 * Say something out loud. Stops whatever is currently playing first.
 * @param {string} text  What to say (used for speech synthesis fallback).
 * @param {object} [options]
 * @param {string} [options.src]  Optional clip to use instead of the manifest's.
 * @param {number} [options.rate] Speech rate for synthesis (slower is clearer for kids).
 * @returns {Promise<void>} resolves when speaking ends.
 */
export async function say(text, options = {}) {
  requestId += 1
  if (muted) return
  await speakOne(text, options)
}

/** Say several lines one after another, with a short pause between them. */
export async function sayAll(lines, { gap = 350 } = {}) {
  const id = ++requestId
  for (const line of lines) {
    if (muted || id !== requestId) return
    const { text, ...options } = typeof line === 'string' ? { text: line } : line
    await speakOne(text, options)
    await new Promise((r) => setTimeout(r, gap))
  }
}
